   119→public(package) fun track_flash_loan_usage<CoinType>(
   120→    self: &mut Referral,
   121→    mut fee: Coin<CoinType>,
   122→    referral_code: String,
   123→    who: address,
   124→    ctx: &mut TxContext
   125→): Coin<CoinType> {
   126→    // verify referral code exists
   127→    assert!(self.code_owner.contains(referral_code), error::referral_invalid_referral_code());
   128→
   129→    let initial_fee = fee.value();
