   133→    let referee_rebates = fee.split(referee_rebates_amount, ctx).into_balance();
   134→
   135→    let fee_remaining = initial_fee - referee_rebates_amount;
   136→
   137→    let referrer_rebates_amount = fee_remaining * self.referrer_discount_bps / DENOMINATOR;
   138→    let referrer_rebates = fee.split(referrer_rebates_amount, ctx).into_balance();
   139→
