public(package) fun increase_usd_qualification(
    self: &mut Referral, 
    who: address, 
    deposit_usd: u64
) {
    if (!self.accumulated_deposit_only_usd.contains(who)) {
        self.accumulated_deposit_only_usd.add( who, deposit_usd);
        return
    };

    let current = self.accumulated_deposit_only_usd.borrow_mut( who );

    // no need accumulation if the amount is more than threshold
    if (*current > self.referrer_deposit_usd_threshold) return;

    *current = *current + deposit_usd;
}

public(package) fun track_flash_loan_usage<CoinType>(
    self: &mut Referral,
    mut fee: Coin<CoinType>,
    referral_code: String,
    who: address,
    ctx: &mut TxContext
): Coin<CoinType> {
    // verify referral code exists
    assert!(self.code_owner.contains(referral_code), error::referral_invalid_referral_code());

    let initial_fee = fee.value();
    let referer = self.look_up_code_owner(referral_code);

    let referee_rebates_amount = initial_fee * self.referee_discount_bps / DENOMINATOR;
    let referee_rebates = fee.split(referee_rebates_amount, ctx).into_balance();

    let fee_remaining = initial_fee - referee_rebates_amount;

    let referrer_rebates_amount = fee_remaining * self.referrer_discount_bps / DENOMINATOR;
    let referrer_rebates = fee.split(referrer_rebates_amount, ctx).into_balance();

    // record user rebates

    self.update_user_rebate<CoinType>(who, referee_rebates);

    emit(ReferralRecordedEvent {
        coin_type: type_name::with_defining_ids<CoinType>(),
        amount: referrer_rebates.value(),
        referee: who,
        referer,
    });
    self.update_user_rebate<CoinType>(referer, referrer_rebates);

    fee
}

public(package) fun generate_referral_code(
    self: &mut Referral,
    random: &Random,
    ctx: &mut TxContext
) {
    let sender = ctx.sender();
    if (self.referrer_code.contains(sender)) {
        abort error::referral_already_has_referral_code()
    };

    // check deposit threshold
    assert!(self.is_qualified_to_create_referral_code(sender), error::referral_not_qualified_to_gen_code());

    // generate unique referral code (keep generating until we find one that doesn't exist)
    let referral_code = generate_random_string(random, REFERRAL_CODE_LENGTH, ctx);
    assert!(!self.code_owner.contains(referral_code), error::referral_invalid_referral_code());

    // Store the mapping: code -> owner and owner -> code
    self.code_owner.add(referral_code, sender);
    self.referrer_code.add( sender, referral_code);
}

public(package) fun claim_rebates<CoinType>(
    self: &mut Referral,
    ctx: &mut TxContext
): Coin<CoinType>{
    assert!(!self.is_claim_paused, error::referral_claim_paused());

    let sender = ctx.sender();
    let coin_type = type_name::with_defining_ids<CoinType>();

    // note that if the user has rebate, that means there must be coin type token

    assert!(self.user_rebates_records.contains(sender), error::referral_no_rebates());

    let user_rebates = self.user_rebates_records.borrow_mut(sender);
    assert!(user_rebates.contains(&coin_type), error::referral_rebate_no_token());

    let amount = *user_rebates.get(&coin_type);

    // if the coin type can be found, it must be greater than 0, sanity check, should never hit
    assert!(amount != 0, error::referral_claim_zero_value_rebate());
    user_rebates.remove(&coin_type);

    // check if balance has enough
    let balance = self.rebates.borrow_mut<TypeName, Balance<CoinType>>(coin_type);  
    balance.split(amount).into_coin(ctx)
}

/// Checks if the user has already binded with the referral code. If not, binds with the referral code. If maybe_referral is none, but user has
/// binded with existing referral code, then use the bineded referral code.
public(package) fun try_map_referral_code(
    self: &mut Referral,
    user: address,
    maybe_referral: Option<String>,
): Option<String> {
    if (self.referee_to_code.contains(user)) {
        let code = *self.referee_to_code.borrow(user);
        return some(code)
    };

    if (maybe_referral.is_none()) {
        return maybe_referral
    };

    let code = *maybe_referral.borrow();

    assert!(self.code_owner.contains(code), error::referral_invalid_referral_code());

    let owner = self.code_owner.borrow(code);
    assert!(owner != user, error::referral_no_self_reference());

    self.referee_to_code.add(user, code);

    maybe_referral
}

public(package) fun get_linked_referral_code(
    self: &Referral,
    user: address,
): Option<String> {
    if (self.referee_to_code.contains(user)) {
        let code = *self.referee_to_code.borrow(user);
        some(code)
    } else {
        none()
    }
}

